+                   SDF::OctetFramework4::magnitude(EXPECTED), 4e-6f);
+    HS_EXPECT_EQ(feature, expected_feature);
+    for (int axis = 0; axis < 4; ++axis)
+      HS_EXPECT_NEAR(OFFSET[axis], EXPECTED[axis], exact ? 0.0f : 4e-6f);
+  };
+  for (int x = -8; x <= 8; ++x)
+    for (int y = -8; y <= 8; ++y)
+      for (int z = -8; z <= 8; ++z)
