+  uint32_t state = 0x19770425;
+  for (int sample = 0; sample < 10000; ++sample) {
+    math::Vec4 point;
+    for (int axis = 0; axis < 4; ++axis) {
+      state = state * 1664525u + 1013904223u;
+      point[axis] =
+          static_cast<float>(state >> 8) * (20.0f / 16777216.0f) - 10.0f;
+    }
+    VERIFY(point, false);
+  }
